int kvm_dev_create(struct kvm *kvm, struct kvm_create_device *cd)
{
	int r;
	struct kvm_device_ops *ops;
	struct kvm_device *dev;
	struct kvm_device *kdev_iter;

	ops = kvm_find_device_ops(cd->type);
	if (!ops)
		return -EINVAL;

	if (cd->flags & KVM_CREATE_DEVICE_TEST)
		return 0;

	dev = kzalloc(sizeof(*dev), GFP_KERNEL);
	if (!dev)
		return -ENOMEM;

	mutex_lock(&kvm->lock);
	list_for_each_entry(kdev_iter, &kvm->devices, list) {
		if (kdev_iter->ops == ops) {
			r = -EEXIST;
			goto unlock;
		}
	}

	dev->ops = ops;
	dev->kvm = kvm;
	r = ops->init(dev);
	if (r)
		goto unlock;

	dev->fd = anon_inode_getfd(ops->name, &kvm_device_fops, dev, O_RDWR);
	if (dev->fd < 0) {
		r = dev->fd;
		goto unlock;
	}

	list_add(&dev->list, &kvm->devices);
	mutex_unlock(&kvm->lock);

	cd->fd = dev->fd;
	return 0;

unlock:
	mutex_unlock(&kvm->lock);
	if (dev->ops->destroy)
		dev->ops->destroy(dev);
	kfree(dev);
	return r;
}

int kvm_dev_create(struct kvm *kvm, struct kvm_create_device *cd)
{
	int r = 0;
	struct kvm_device_ops *ops;
	struct kvm_device *dev;
	struct kvm_device *dev2;

	if (!cd->type)
		return -EINVAL;

	ops = kvm_find_device_ops(cd->type);
	if (!ops)
		return -ENODEV;

	if (cd->flags & KVM_CREATE_DEVICE_TEST)
		return 0;

	dev = kzalloc(sizeof(*dev), GFP_KERNEL);
	if (!dev)
		return -ENOMEM;

	dev->ops = ops;
	dev->kvm = kvm;

	mutex_lock(&kvm->lock);
	list_for_each_entry(dev2, &kvm->devices, list) {
		if (dev2->id == cd->id) {
			r = -EEXIST;
			goto unlock;
		}
	}

	dev->id = cd->id;
	list_add(&dev->list, &kvm->devices);
	mutex_unlock(&kvm->lock);

	if (ops->init && ops->init(dev)) {
		r = -EINVAL;
		goto fail;
	}

	r = kvm_device_get_file_descriptor(dev);
	if (r < 0)
		goto fail;

	cd->fd = r;
	return 0;

fail:
	mutex_lock(&kvm->lock);
	list_del(&dev->list);
	mutex_unlock(&kvm->lock);
	kfree(dev);
	return r;

unlock:
	mutex_unlock(&kvm->lock);
	kfree(dev);
	return r;
}

int kvm_vm_create_device(struct kvm *kvm, struct kvm_create_device *cd)
{
	int ret;
	struct kvm_device_ops *ops;

	if (cd->type >= KVM_DEV_TYPE_MAX)
		return -EINVAL;

	ops = kvm_dev_get_ops(cd->type);
	if (!ops)
		return -EINVAL;

	if (cd->flags & KVM_CREATE_DEVICE_TEST)
		return 0;

	cd->fd = -1;

	kvm_get_kvm(kvm);
	ret = -ENOMEM;
	dev = kmem_cache_zalloc(kvm_kmem_cache, GFP_KERNEL);
	if (!dev)
		goto out_put_kvm;

	dev->ops = ops;
	dev->kvm = kvm;

	mutex_lock(&kvm->lock);
	list_add(&dev->list, &kvm->devices);
	mutex_unlock(&kvm->lock);

	if (ops->init && (ret = ops->init(dev, cd->flags))) {
		mutex_lock(&kvm->lock);
		list_del(&dev->list);
		mutex_unlock(&kvm->lock);
		goto out_free_dev;
	}

	ret = kvm_dev_ioctl_create_device(dev, &cd->fd);
	if (ret)
		goto out_cleanup_dev;

	cd->fd = ret;

	return 0;

out_cleanup_dev:
	if (ops->destroy)
		ops->destroy(dev);
out_free_dev:
	kmem_cache_free(kvm_kmem_cache, dev);
out_put_kvm:
	kvm_put_kvm(kvm);
	return ret;
}

int kvm_dev_create(struct kvm *kvm, struct kvm_create_device *cd)
{
	int r, fd;
	struct kvm_device_ops *ops;
	struct kvm_device *dev;

	ops = kvm_find_device_ops(cd->type);
	if (!ops)
		return -EINVAL;

	if (cd->flags & KVM_CREATE_DEVICE_TEST) {
		ops->release = NULL;
		return 0;
	}

	dev = kvmalloc(sizeof(*dev), GFP_KERNEL);
	if (!dev)
		return -ENOMEM;

	kvm_lock(kvm);
	r = ops->init_device(dev, cd);
	if (r) {
		kvm_unlock(kvm);
		goto out;
	}

	list_add(&dev->list, &kvm->devices);
	kvm->nr_devices++;
	kvm_unlock(kvm);

	fd = kvm_create_ioctl_device(kvm, dev, ops);
	if (fd < 0) {
		kvm_remove_device(dev);
		goto out;
	}

	cd->fd = fd;
	return 0;

out:
	kvfree(dev);
	return r;
}

int kvm_dev_create(struct kvm *kvm, struct kvm_create_device *cd)
{
	int r;
	struct kvm_device_ops *ops;
	struct kvm_device *dev;
	bool test = cd->test;

	ops = kvm_find_device_ops(cd->type);
	if (!ops)
		return -EINVAL;

	dev = kzalloc(sizeof(*dev), GFP_KERNEL);
	if (!dev)
		return -ENOMEM;

	kvm_dev_hold(ops);
	dev->ops = ops;
	dev->kvm = kvm;

	mutex_lock(&kvm->lock);
	r = -EEXIST;
	list_for_each_entry(dev, &kvm->devices, list)
		if (dev->id == cd->id)
			goto unlock;
	list_add(&dev->list, &kvm->devices);
	mutex_unlock(&kvm->lock);

	if (ops->init && (r = ops->init(dev)))
		goto fail;

	cd->fd = get_ksysfs_fd(dev);
	if (cd->fd < 0) {
		r = cd->fd;
		goto fail;
	}

 out:
	if (!r)
		cd->fd = get_ksysfs_fd(dev);
	if (test) {
		if (!r)
			put_ksysfs_fd(cd->fd);
		r = 0;
	}
	return r;

 fail:
	kvm_remove_device(dev);
	kvm_dev_drop(dev->ops);
	goto out;
}
